import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;

public class Main {
    static final Object A = new Object();
    static final Object B = new Object();
    static int progress = 0;

    static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    public static void main(String[] args) throws Exception {
        ThreadMXBean mx = ManagementFactory.getThreadMXBean();

        Thread o1 = new Thread(() -> {
            for (int i = 0; i < 2000; i++) { synchronized (A) { synchronized (B) { progress++; } } }
        }, "ordered-1");
        Thread o2 = new Thread(() -> {
            for (int i = 0; i < 2000; i++) { synchronized (A) { synchronized (B) { progress++; } } }
        }, "ordered-2");
        o1.start(); o2.start();
        o1.join(5000L); o2.join(5000L);
        long[] none = mx.findDeadlockedThreads();
        System.out.println("[prevent] ordered locking progress  = " + progress);
        System.out.println("[prevent] deadlocked threads found  = " + (none == null ? 0 : none.length));

        Thread d1 = new Thread(() -> {
            synchronized (A) { sleep(120L); synchronized (B) { System.out.println("d1 got both locks (unreachable here)"); } }
        }, "deadlock-1");
        Thread d2 = new Thread(() -> {
            synchronized (B) { sleep(120L); synchronized (A) { System.out.println("d2 got both locks (unreachable here)"); } }
        }, "deadlock-2");
        d1.setDaemon(true);
        d2.setDaemon(true);
        d1.start(); d2.start();
        Thread.sleep(600L);

        long[] found = mx.findDeadlockedThreads();
        System.out.println("[detect ] deadlocked threads found  = " + (found == null ? 0 : found.length));
        System.out.println("[detect ] deadlock confirmed        = " + (found != null && found.length == 2));
        System.out.println("[hint   ] fix: global lock ordering, or tryLock(timeout)");
    }
}
